import type {ChatSession} from '../types/session.js';
import type {ToolRegistry, ToolContext} from './tools/registry.js';
import type {
  AIProvider,
  Message,
  MessageChunk,
  SendMessageParams,
  ToolCall,
  ToolResultContent,
  UsageMetadata,
} from '../types/ai.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
import {toMessages, createContextConfig} from './conversationContext.js';
import type {ContextConfig} from './conversationContext.js';
import {
  shouldContinueToolLoop,
  collectText,
  buildToolCallMessages,
  collectToolCalls,
  extractStopReason,
  extractUsage,
} from './orchestratorHelpers.js';
import {appendEntry} from './entryMutations.js';
import {log} from '../shared/logger.js';

const DEFAULT_MAX_TOOL_ROUNDS = 5;

export interface OrchestratorHooks {
  beforeSession?: (session: ChatSession) => Promise<void>;
  afterSession?: (session: ChatSession) => Promise<void>;
  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
  onError?: (session: ChatSession, error: Error) => Promise<void>;
}

export interface ChatOrchestrator {
  processMessage(session: ChatSession): Promise<string>;
  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
}

export interface ChatOrchestratorOptions {
  maxToolRounds?: number;
  contextConfig?: Partial<ContextConfig>;
  promptBuilderOptions?: PromptBuilderOptions;
  hooks?: OrchestratorHooks;
}

interface ToolExecutionResult {
  clientMessages: OutgoingMessage[];
  suppressOutput: boolean;
}
export function createChatOrchestrator(
  provider: AIProvider,
  promptBuilder: PromptBuilder,
  toolRegistry?: ToolRegistry,
  options?: ChatOrchestratorOptions
): ChatOrchestrator {
  const maxToolRounds = options?.maxToolRounds ?? DEFAULT_MAX_TOOL_ROUNDS;
  const contextConfig = createContextConfig(options?.contextConfig);
  const toolInstructions = toolRegistry?.getPromptInstructions();
  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
  const tools = toolRegistry?.getDefinitions();
  const hooks = options?.hooks;

  return {
    async processMessage(session: ChatSession): Promise<string> {
      return collectText(this.processMessageStream(session));
    },

    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
      if (hooks?.beforeSession) await hooks.beforeSession(session);

      try {
        let userMessage = lastUserContent(session);

        if (hooks?.beforeUserInput) {
          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
        }

        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);

        const systemPrompt = hooks?.beforeModelResponse
          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
          : baseSystemPrompt;

        const messages: Message[] = toMessages(session.entries, contextConfig);
        let lastUsage: UsageMetadata | undefined;
        let responseText = '';

        for (let round = 0; round <= maxToolRounds; round++) {
          log.info('orchestrator', 'starting round', {round});
          const pendingToolCalls: ToolCall[] = [];

          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
          responseText += outcome.text;
          lastUsage = outcome.usage ?? lastUsage;

          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;

          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
          const {clientMessages, suppressOutput} = await executeToolCalls(
            pendingToolCalls,
            messages,
            toolRegistry!,
            session
          );
          log.info('orchestrator', 'tool execution complete', {
            clientMessageCount: clientMessages.length,
            clientMessageTypes: clientMessages.map(m => m.type),
            suppressOutput,
          });

          if (clientMessages.length > 0) {
            yield {type: 'tool_result' as const, clientMessages};
          }

          if (suppressOutput) {
            yield {type: 'suppress_output' as const};
          }
        }

        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
      } catch (error) {
        if (hooks?.onError && error instanceof Error) {
          await hooks.onError(session, error);
        }
        throw error;
      } finally {
        if (hooks?.afterSession) await hooks.afterSession(session);
      }
    },
  };
}

interface RoundOutcome {
  stopReason: string;
  text: string;
  usage?: UsageMetadata;
}

// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
async function* streamRound(
  provider: AIProvider,
  request: SendMessageParams,
  pendingToolCalls: ToolCall[]
): AsyncGenerator<MessageChunk, RoundOutcome> {
  let stopReason = '';
  let text = '';
  let usage: UsageMetadata | undefined;

  for await (const chunk of provider.sendMessage(request)) {
    yield chunk;
    collectToolCalls(chunk, pendingToolCalls);
    stopReason = extractStopReason(chunk) ?? stopReason;
    usage = extractUsage(chunk) ?? usage;
    if (chunk.type === 'text') text += chunk.text;
  }

  return {stopReason, text, usage};
}

// A changed message is also written back to the session's last user entry.
async function rewriteUserMessage(
  session: ChatSession,
  userMessage: string,
  hook: (session: ChatSession, userMessage: string) => Promise<string>
): Promise<string> {
  const modified = await hook(session, userMessage);
  if (modified === userMessage) return userMessage;

  updateLastUserContent(session, modified);
  return modified;
}

function lastUserContent(session: ChatSession): string {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') return entry.content;
  }
  return '';
}

function updateLastUserContent(session: ChatSession, content: string): void {
  for (let i = session.entries.length - 1; i >= 0; i--) {
    const entry = session.entries[i];
    if (entry.role === 'user') {
      entry.content = content;
      return;
    }
  }
}

async function executeToolCalls(
  pendingToolCalls: ToolCall[],
  messages: Message[],
  toolRegistry: ToolRegistry,
  session: ChatSession
): Promise<ToolExecutionResult> {
  messages.push(buildToolCallMessages(pendingToolCalls));

  const context: ToolContext = {
    userId: session.userId,
    sessionId: session.sessionId,
    workspaceId: session.workspaceId,
    authHeaders: session.authHeaders,
  };

  const responses = await Promise.all(
    pendingToolCalls.map(async tc => {
      const response = await toolRegistry.execute(tc.name, tc.input, context);
      return {tc, response};
    })
  );

  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
    type: 'tool_result' as const,
    toolUseId: tc.id,
    content: response.result,
  }));
  messages.push({role: 'user', content: toolResults});

  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);

  return {
    clientMessages: assignEntryIndices(rawClientMessages, session),
    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
  };
}

function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
  return clientMessages.map(msg => {
    if (msg.type !== 'entry_upsert') return msg;
    const index = appendEntry(session, msg.entry);
    return {...msg, index};
  });
}
import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validators = new WeakMap<object, ValidateFunction>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const compiled = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator: compiled});
  }

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      throw new Error(
        `Unable to compile inputSchema for tool ${definition.name}: ${error instanceof Error ? error.message : String(error)}`,
        {cause: error}
      );
    }
  }

  private validatorFor(definition: ToolDefinition): ValidateFunction {
    const schema = definition.inputSchema;
    const cached = this.validators.get(schema);
    if (cached) return cached;
    const validator = this.compile(definition);
    this.validators.set(schema, validator);
    return validator;
  }

  private normalizeInstancePath(instancePath?: string): string | undefined {
    if (!instancePath?.startsWith('.')) return instancePath;
    return instancePath
      .split('.')
      .filter(Boolean)
      .map(property => `/${property}`)
      .join('');
  }

  private validationMessage(validator: ValidateFunction): string {
    const error = validator.errors?.[0] as
      | {
          instancePath?: string;
          keyword: string;
          params: {missingProperty?: unknown; type?: unknown};
          schemaPath?: string;
        }
      | undefined;
    if (!error) return 'Tool input does not match the registered inputSchema';
    const schemaPath = error.schemaPath ?? '';
    const schemaProperties = [...schemaPath.matchAll(/\/properties\/([^/]+)/g)].map(match => match[1]);
    const instancePath = error.instancePath ?? (error as {dataPath?: string}).dataPath;
    const normalizedPath = this.normalizeInstancePath(instancePath);
    const path = normalizedPath || (schemaProperties.length > 0 ? `/${schemaProperties.join('/')}` : '(input)');
    if (error.keyword === 'required') {
      return `${path} must have required property ${String(error.params.missingProperty)}`;
    }
    if (error.keyword === 'type') {
      return `${path || '(input)'} must be ${String(error.params.type)}`;
    }
    return `${path || '(input)'} violates ${error.keyword}`;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes a registered tool after validating input against its schema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.validatorFor(definition);
    if (!validator(input)) {
      const result = this.validationMessage(validator);
      log.warn('tool', 'input rejected', {name, result});
      return {result};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov

#!/usr/bin/env node
// Re-points specs' [validated by](../../src/X.test.ts#Lnn) anchors after
// edits to the cited file - any cited
// repository file, whatever its kind: each anchor's line number is
// resolved to the content it cited in the base ref's copy of that file,
// that content is found in the working copy (compared with quotes and
// whitespace dropped, so a formatter pass is not drift), and the anchor is
// rewritten to the match whose surrounding lines agree with the baseline's. When the cited
// content occurs on several working lines, each candidate is scored by how
// many of the baseline's neighbouring lines it reproduces at the same offsets;
// a candidate whose context uniquely wins is chosen, and a tie is reported as
// ambiguous for manual fix (exit 1 in both modes) instead of guessing. An
// anchor into a file built of repeated blocks - a workflow whose jobs share an
// identical setup - must therefore cite a line unique to its own step, because
// the resolver refuses to guess between indistinguishable candidates.
//
// Usage:
//   node scripts/repoint-spec-anchors.mjs [--check] [base-ref]
//
// base-ref defaults to origin/main and must be the baseline the anchors were
// last correct against. Baseline line numbers are read from the base ref's
// copy of each spec, never from the working copy, so re-running against the
// same baseline is a no-op instead of a second translation. A spec whose
// anchor set (the ordered list of test paths it cites) differs from the base
// ref is skipped whole: its anchors were authored against the working tree,
// and no baseline exists to repoint them from. An individual anchor whose
// line number differs from the base spec's at the same position was
// deliberately retargeted by a spec edit: it is accepted as authored, never
// rewritten, and reported as "retargeted (not checked)".
//
// Independent of any baseline, every anchor must land on a line that exists
// and carries content: an anchor whose target file is missing, whose line is
// beyond the end of the file, or whose line is blank or closing punctuation
// is reported as rotten and fails the run in both modes. An anchor
// into a test file must additionally land on the it/test/describe declaration
// itself, because a line inside a test body names no case a reader can check.
// Non-test targets - a workflow, a config, package.json - are exempt from that
// last check: they have no declaration to land on.
//
// Also independent of any baseline, a short-form [Lnnn](...#Lmmm) label must
// name the line its own href points at. Labels are re-synced to their href
// after the anchor rewrite, so a repointed href carries its label with it;
// --check reports label/href disagreement as mislabelled and fails.
// --check rewrites nothing, so it judges each label against its current
// (un-repointed) href: a stale href is reported as stale, and once a plain run
// repoints it the label follows, so the two runs still converge in one pass.
//
// --check rewrites nothing and exits 1 when any anchor is stale (its baseline
// content now lives on a different line), unresolved (that content no
// longer exists), rotten, or mislabelled. Without --check, stale anchors are
// rewritten in place, labels are synced, and unresolved or rotten ones are
// reported for manual fix with exit 1; a rotten anchor the rewrite itself
// repoints needs no manual fix and is not reported.

import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, normalize } from "node:path";
import process from "node:process";
import { splitArgs } from "./lib/cli-args.mjs";

const TRACKED_PATH = String.raw`(?:\.\.\/)+(?:scripts\/[\w./-]+|[\w./-]+\.[A-Za-z]+)`;
const ANCHOR = new RegExp(String.raw`(${TRACKED_PATH})#L(\d+)`, "g");

// A short-form [Lnnn](../../src/X.test.ts#Lmmm) link: its visible label is a
// bare line number that must equal the href's #L number. The label has no
// meaning apart from the href, so it is force-synced to the href even when the
// href was manually retargeted; descriptive labels ([validated by], ...) never
// match and are never touched.
const LABEL_LINK = new RegExp(String.raw`\[L(\d+)\]\((${TRACKED_PATH})#L(\d+)\)`, "g");

const { flags, positional } = splitArgs(process.argv.slice(2));

if (flags.some((flag) => flag !== "--check") || positional.length > 1) {
  process.stderr.write("usage: repoint-spec-anchors.mjs [--check] [base-ref]\n");
  process.exit(2);
}
const checkMode = flags.includes("--check");
const baseRef = positional[0] ?? "origin/main";

const root = process.cwd();

const refResolves = () => {
  try {
    execFileSync("git", ["rev-parse", "--verify", "--quiet", `${baseRef}^{commit}`], {
      cwd: root,
      stdio: "ignore",
    });

    return true;
  } catch {
    return false;
  }
};

if (!refResolves()) {
  process.stderr.write(`base ref does not resolve to a commit: ${baseRef}\n`);
  process.exit(2);
}

const readBaseFile = (path) => {
  try {
    return execFileSync("git", ["show", `${baseRef}:${path}`], {
      cwd: root,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    });
  } catch {
    return null;
  }
};

const baseFileCache = new Map();
const baseFile = (path) => {
  if (!baseFileCache.has(path)) {
    baseFileCache.set(path, readBaseFile(path));
  }

  return baseFileCache.get(path);
};

const workingFileCache = new Map();
const workingFile = (path) => {
  if (workingFileCache.has(path)) {
    return workingFileCache.get(path);
  }
  const fullPath = join(root, path);
  const content = existsSync(fullPath) ? readFileSync(fullPath, "utf8") : null;

  workingFileCache.set(path, content);

  return content;
